import hashlib
import os

from langfuse import Langfuse

langfuse = Langfuse()

# Fraction of sessions that see a new prompt version before it is promoted.
CANARY_PERCENT = int(os.environ.get("PROMPT_CANARY_PERCENT", "0"))


def _in_canary(session_id: str) -> bool:
    bucket = int(hashlib.sha256(session_id.encode()).hexdigest(), 16) % 100
    return bucket < CANARY_PERCENT


def build_messages(session_id: str, user_input: str) -> list[dict]:
    if _in_canary(session_id):
        prompt = langfuse.get_prompt("support-agent", label="canary")
    else:
        prompt = langfuse.get_prompt("support-agent", label="production")
    return prompt.compile(question=user_input)
